package com.johnny.hotel;import com.johnny.hotel.businessdate.*;import com.johnny.hotel.cashier.*;import com.johnny.hotel.cashier.CashierModels.*;import org.junit.jupiter.api.*;import java.math.*;import java.time.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class CashierPostingServiceTest{CashierMapper db;BusinessDateService dates;CashierPostingService service;@BeforeEach void init(){db=mock(CashierMapper.class);dates=mock(BusinessDateService.class);service=new CashierPostingService(db,dates,Clock.fixed(Instant.EPOCH,ZoneOffset.UTC));when(dates.postingDate()).thenReturn(LocalDate.of(2026,9,24));}
 @Test void cashPaymentPostsExactlyOneDrawerInAndRetryIsIdempotent(){var shift=Shift.builder().id(2L).drawerId(1L).operatorUserId(7L).status("ACTIVE").build();when(db.activeByOperator(7L)).thenReturn(shift);when(db.lockDrawer(1L)).thenReturn(Drawer.builder().id(1L).activeShiftId(2L).currency("CNY").build());when(db.insertMovement(any())).thenAnswer(i->{((Movement)i.getArgument(0)).setId(5L);return 1;});var first=service.post(7L,"IN","CASH_PAYMENT",new BigDecimal("300.00"),"CNY","FOLIO_PAYMENT",11L,"cash-payment-11",null);when(db.movementBySource("FOLIO_PAYMENT",11L)).thenReturn(first);service.post(7L,"IN","CASH_PAYMENT",new BigDecimal("300.00"),"CNY","FOLIO_PAYMENT",11L,"cash-payment-11",null);verify(db,times(1)).insertMovement(any());assertEquals("IN",first.getDirection());}
 @Test void cardPaymentHasNoCashierPostingCallByDesign(){verifyNoInteractions(db,dates);}
}
